import '../models/medicine.dart';

/// Comprehensive clinical knowledge engine for medicines in Bangladesh.
///
/// Ensures every medicine in the catalog displays complete, structured, and
/// medically accurate clinical guidance in clear Bengali covering:
/// - রোগের নির্দেশনা (Indications)
/// - ফার্মাকোলজি (Pharmacology)
/// - ডোজ ও ব্যবহারবিধি (Dosage & Administration / Pediatric Use)
/// - অন্যান্য ওষুধের সাথে ক্রিয়া (Drug Interactions)
/// - যেসব ক্ষেত্রে ব্যবহার নিষিদ্ধ (Contraindications)
/// - পার্শ্বপ্রতিক্রিয়া (Side Effects)
/// - গর্ভাবস্থা ও স্তন্যদান (Pregnancy & Lactation)
/// - সতর্কতা ও সাবধানতা (Precautions & Warnings)
/// - অতিরিক্ত ডোজের প্রভাব (Overdose Effects)
/// - থেরাপিউটিক শ্রেণি (Therapeutic Class)
/// - সংরক্ষণ পদ্ধতি (Storage Conditions)
/// - সাধারণ প্রশ্ন (Common Questions / FAQs)
abstract final class ClinicalKnowledgeEngine {
  /// Returns a rich clinical profile in Bengali tailored to [medicine].
  static Map<String, String> getClinicalSections(Medicine medicine) {
    final brand = medicine.brandName.trim();
    final generic = (medicine.genericName ?? '').trim();
    final lowerGeneric = generic.toLowerCase();
    final form = (medicine.dosageForm ?? medicine.form.name).trim();
    final strength = (medicine.strength ?? '').trim();
    final company = (medicine.company ?? '').trim();

    // Check specific generic matches
    if (lowerGeneric.contains('paracetamol') || lowerGeneric.contains('acetaminophen')) {
      return _paracetamol(brand, strength, form, company);
    }
    if (lowerGeneric.contains('esomeprazole')) {
      return _esomeprazole(brand, strength, form, company);
    }
    if (lowerGeneric.contains('omeprazole')) {
      return _omeprazole(brand, strength, form, company);
    }
    if (lowerGeneric.contains('pantoprazole')) {
      return _pantoprazole(brand, strength, form, company);
    }
    if (lowerGeneric.contains('rabeprazole')) {
      return _rabeprazole(brand, strength, form, company);
    }
    if (lowerGeneric.contains('ciprofloxacin')) {
      return _ciprofloxacin(brand, strength, form, company);
    }
    if (lowerGeneric.contains('azithromycin')) {
      return _azithromycin(brand, strength, form, company);
    }
    if (lowerGeneric.contains('cefixime')) {
      return _cefixime(brand, strength, form, company);
    }
    if (lowerGeneric.contains('cefuroxime')) {
      return _cefuroxime(brand, strength, form, company);
    }
    if (lowerGeneric.contains('cephradine')) {
      return _cephradine(brand, strength, form, company);
    }
    if (lowerGeneric.contains('ceftriaxone')) {
      return _ceftriaxone(brand, strength, form, company);
    }
    if (lowerGeneric.contains('amoxicillin')) {
      return _amoxicillin(brand, strength, form, company);
    }
    if (lowerGeneric.contains('flucloxacillin')) {
      return _flucloxacillin(brand, strength, form, company);
    }
    if (lowerGeneric.contains('metronidazole')) {
      return _metronidazole(brand, strength, form, company);
    }
    if (lowerGeneric.contains('aceclofenac')) {
      return _aceclofenac(brand, strength, form, company);
    }
    if (lowerGeneric.contains('diclofenac')) {
      return _diclofenac(brand, strength, form, company);
    }
    if (lowerGeneric.contains('ketorolac')) {
      return _ketorolac(brand, strength, form, company);
    }
    if (lowerGeneric.contains('etoricoxib')) {
      return _etoricoxib(brand, strength, form, company);
    }
    if (lowerGeneric.contains('naproxen')) {
      return _naproxen(brand, strength, form, company);
    }
    if (lowerGeneric.contains('ibuprofen')) {
      return _ibuprofen(brand, strength, form, company);
    }
    if (lowerGeneric.contains('montelukast')) {
      return _montelukast(brand, strength, form, company);
    }
    if (lowerGeneric.contains('fexofenadine')) {
      return _fexofenadine(brand, strength, form, company);
    }
    if (lowerGeneric.contains('cetirizine') || lowerGeneric.contains('levocetirizine')) {
      return _cetirizine(brand, strength, form, company);
    }
    if (lowerGeneric.contains('domperidone')) {
      return _domperidone(brand, strength, form, company);
    }
    if (lowerGeneric.contains('fluconazole')) {
      return _fluconazole(brand, strength, form, company);
    }
    if (lowerGeneric.contains('metformin')) {
      return _metformin(brand, strength, form, company);
    }
    if (lowerGeneric.contains('pregabalin')) {
      return _pregabalin(brand, strength, form, company);
    }
    if (lowerGeneric.contains('clonazepam') || lowerGeneric.contains('alprazolam') || lowerGeneric.contains('bromazepam')) {
      return _anxiolytic(brand, generic, strength, form, company);
    }
    if (lowerGeneric.contains('calcium') || lowerGeneric.contains('cholecalciferol') || lowerGeneric.contains('vitamin d')) {
      return _calciumVitaminD(brand, generic, strength, form, company);
    }
    if (lowerGeneric.contains('doxophylline') || lowerGeneric.contains('salbutamol') || lowerGeneric.contains('levosalbutamol')) {
      return _bronchodilator(brand, generic, strength, form, company);
    }
    if (lowerGeneric.contains('losartan') || lowerGeneric.contains('amlodipine') || lowerGeneric.contains('telmisartan') || lowerGeneric.contains('bisoprolol')) {
      return _antihypertensive(brand, generic, strength, form, company);
    }
    if (lowerGeneric.contains('atorvastatin') || lowerGeneric.contains('rosuvastatin')) {
      return _statin(brand, generic, strength, form, company);
    }
    if (lowerGeneric.contains('levofloxacin')) {
      return _levofloxacin(brand, strength, form, company);
    }
    if (lowerGeneric.contains('ondansetron')) {
      return _ondansetron(brand, strength, form, company);
    }
    if (lowerGeneric.contains('vitamin b') || lowerGeneric.contains('thiamine') || lowerGeneric.contains('cyanocobalamin') || lowerGeneric.contains('pyridoxine')) {
      return _vitaminB(brand, strength, form, company);
    }
    if (lowerGeneric.contains('ambroxol') || lowerGeneric.contains('bromhexine')) {
      return _ambroxol(brand, strength, form, company);
    }
    if (lowerGeneric.contains('dexlansoprazole')) {
      return _dexlansoprazole(brand, strength, form, company);
    }
    if (lowerGeneric.contains('gliclazide') || lowerGeneric.contains('glimepiride') || lowerGeneric.contains('glipizide')) {
      return _antidiabeticSulfonylurea(brand, generic, strength, form, company);
    }
    if (lowerGeneric.contains('baclofen') || lowerGeneric.contains('tolperisone') || lowerGeneric.contains('tizanidine')) {
      return _baclofen(brand, generic, strength, form, company);
    }
    if (lowerGeneric.contains('albendazole') || lowerGeneric.contains('mebendazole')) {
      return _albendazole(brand, strength, form, company);
    }
    if (lowerGeneric.contains('meropenem') || lowerGeneric.contains('imipenem')) {
      return _meropenem(brand, strength, form, company);
    }

    // Classify by broad therapeutic category or dosage form
    return _synthesizeUniversal(brand, generic, strength, form, company);
  }

  // ─────────────────────────────────────────────────────────────────────────────
  // 1. Paracetamol
  // ─────────────────────────────────────────────────────────────────────────────
  static Map<String, String> _paracetamol(String brand, String strength, String form, String company) => {
    'indications': '$brand ($strength $form) জ্বর, সর্দি-কাশি জনিত শারীরিক অস্বস্তি, মাথাব্যথা, মাইগ্রেন, দাঁতব্যথা, কানের ব্যথা, গলাব্যথা, পেশির ব্যথা, স্নায়বিক ব্যথা, মাসিকের ব্যথা এবং বাত ও অস্টিওআর্থ্রাইটিসজনিত ব্যথা নিরাময়ে কার্যকরভাবে নির্দেশিত।',
    'pharmacology': 'প্যারাসিটামল কেন্দ্রীয় স্নায়ুতন্ত্রে প্রোস্টাগ্ল্যান্ডিন সংশ্লেষণ প্রতিরোধ করে বেদনানাশক (অ্যানালজেসিক) হিসেবে কাজ করে। মস্তিষ্কের হাইপোথ্যালামিক তাপ-নিয়ন্ত্রণ কেন্দ্রে ক্রিয়া করে ত্বকের রক্তনালী প্রসারিত করে ঘাম ঝরানোর মাধ্যমে শরীরের উচ্চ তাপমাত্রা হ্রাস করে (অ্যান্টিপাইরেটিক)।',
    'dosage_and_administration': 'প্রাপ্তবয়স্ক ও ১২ বছরের ঊর্ধ্বদের জন্য: ৫০০ মি.গ্রা. থেকে ১০০০ মি.গ্রা. (১-২টি ট্যাবলেট) প্রতি ৪ থেকে ৬ ঘণ্টা পর পর সেব্য। ২৪ ঘণ্টায় সর্বোচ্চ ৪ গ্রাম (৪০০০ মি.গ্রা.)-এর বেশি সেবন করা নিষেধ।\n\nশিশুদের জন্য (সিরাপ/ড্রপস): ১০ থেকে ১৫ মি.গ্রা./কেজি শরীরের ওজন অনুযায়ী প্রতি ৪-৬ ঘণ্টা পর পর (২৪ ঘণ্টায় সর্বোচ্চ ৪ বার)। চিকিৎসকের পরামর্শ ব্যতীত একটানা ৩ দিনের বেশি ব্যবহার করা উচিত নয়। ওষুধটি খাবারের আগে বা পরে পর্যাপ্ত পানিসহ সেবন করা যায়।',
    'interaction': 'দীর্ঘদিন উচ্চমাত্রায় প্যারাসিটামল ব্যবহারে ওয়ারফারিন জাতীয় রক্ত পাতলাকারী ওষুধের প্রভাব বৃদ্ধি পেতে পারে। কোলস্টাইরামিন প্যারাসিটামলের শোষণ কমিয়ে দেয় এবং মেটোক্লোপ্রামাইড বা ডমপেরিডন শোষণ বৃদ্ধি করে। অ্যালকোহল সেবনের সাথে প্যারাসিটামল নিলে লিভারের ক্ষতির ঝুঁকি মারাত্মকভাবে বেড়ে যায়।',
    'contraindications': 'প্যারাসিটামলের প্রতি অতিসংবেদনশীলতা এবং তীব্র যকৃৎ বা লিভারের অকার্যকারিতায় (Severe hepatic impairment) এই ওষুধ সম্পূর্ণরূপে নিষিদ্ধ।',
    'side_effects': 'প্রস্তাবিত মাত্রায় পার্শ্বপ্রতিক্রিয়া খুবই বিরল। কদাচিৎ ত্বকে অ্যালার্জি, র‍্যাশ, চুলকানি হতে পারে। দীর্ঘদিন অতিরিক্ত মাত্রায় সেবনে হেপাটোটক্সিসিটি (লিভারের ক্ষতি), প্যানক্রিয়াটাইটিস ও রক্তকণিকার ঘাটতি (নিউট্রোপেনিয়া) দেখা দিতে পারে।',
    'pregnancy_and_lactation': 'ইউএস এফডিএ প্রেগনেন্সি ক্যাটাগরি B। গর্ভাবস্থায় ও স্তন্যদানকালে নির্দেশিত মাত্রায় প্যারাসিটামল সবচেয়ে নিরাপদ ব্যথানাশক ও জ্বরনাশক হিসেবে চিকিৎসকদের প্রথম পছন্দ।',
    'precautions_and_warnings': 'লিভার বা কিডনির জটিলতা থাকলে চিকিৎসকের পরামর্শে সতর্কতা অবলম্বন করুন। একই সাথে প্যারাসিটামলযুক্ত একাধিক ওষুধ (যেমন ঠান্ডার কম্বিনেশন ক্যাপসুল) সেবন করবেন না, কারণ এতে অজান্তেই অতিরিক্ত মাত্রা হয়ে যেতে পারে।',
    'overdose_effects': 'অতিরিক্ত মাত্রায় প্যারাসিটামল সেবন করলে প্রথম ২৪ ঘণ্টায় বমি বমি ভাব, বমি, ক্ষুধামন্দা, পেটে ব্যথা দেখা দেয় এবং পরবর্তীতে মারাত্মক লিভার ড্যামেজ হতে পারে। অতিরিক্ত ডোজ গ্রহণের সন্দেহ হলে অবিলম্বে হাসপাতালে জরুরি চিকিৎসা ও প্রতিষেধক (N-acetylcysteine) নিতে হবে।',
    'therapeutic_class': 'Non-Opioid Analgesics & Antipyretics (বেদনানাশক ও জ্বরনাশক)।',
    'storage_conditions': 'আলো ও সরাসরি তাপ থেকে দূরে, ৩০° সেলসিয়াসের নিচে শুষ্ক স্থানে সংরক্ষণ করুন। শিশুদের নাগালের বাইরে রাখুন।',
    'common_questions': '১. ওষুধটি কি খালি পেটে খাওয়া যায়?\n- হ্যাঁ, প্যারাসিটামল খালি পেটে বা ভরা পেটে খাওয়া যায়। তবে যাদের গ্যাস্ট্রিকের সমস্যা আছে তারা খাবার পর খেলে ভালো।\n\n২. জ্বর কমলে কি ওষুধ বন্ধ করা যাবে?\n- হ্যাঁ, জ্বর বা ব্যথা ভালো হয়ে গেলে প্যারাসিটামল বন্ধ করে দেওয়া যায়। অ্যান্টিবায়োটিকের মতো কোর্স শেষ করার প্রয়োজন নেই।',
