  // ─────────────────────────────────────────────────────────────────────────────
  // 2. Esomeprazole
  // ─────────────────────────────────────────────────────────────────────────────
  static Map<String, String> _esomeprazole(String brand, String strength, String form, String company) => {
    'indications': '$brand ($strength $form) গ্যাস্ট্রোইসোফেজিয়াল রিফ্লাক্স ডিজিজ (GERD), এসিডিটি, বুকজ্বালা, গ্যাস্ট্রিক ও ডিওডেনাল আলসার, এনএসএআইডি (ব্যথানাশক) ওষুধজনিত পেটের ক্ষত প্রতিরোধ এবং এইচ. পাইলোরি (H. pylori) ব্যাকটেরিয়া নির্মূলে ট্রিপল থেরাপির অংশ হিসেবে নির্দেশিত।',
    'pharmacology': 'এসোমিপ্রাজল একটি প্রোটন পাম্প ইনহিবিটর (PPI)। এটি পাকস্থলীর প্যারাইটাল কোষের H+/K+ ATPase এনজাইম সিস্টেমকে বিশেষভাবে প্রতিরোধ করে গ্যাস্ট্রিক অ্যাসিডের চূড়ান্ত নিঃসরণকে সরাসরি বন্ধ করে, ফলে পাকস্থলীর অতিরিক্ত অম্লতা ও জ্বালাপোড়া দ্রুত প্রশমিত হয়।',
    'dosage_and_administration': 'প্রাপ্তবয়স্কদের জন্য: ২০ মি.গ্রা. থেকে ৪০ মি.গ্রা. দিনে একবার সকালে খাবারের ৩০ থেকে ৬০ মিনিট পূর্বে সম্পূর্ণ এক গ্লাস পানিসহ গিলে খেতে হবে। ট্যাবলেট বা ক্যাপসুল চিবানো বা ভেঙে গুঁড়ো করা যাবে না। তীব্র আলসারের ক্ষেত্রে চিকিৎসকের পরামর্শে দিনে দুইবার দেওয়া হতে পারে (সাধারণত ৪-৮ সপ্তাহ)।',
