  // ─────────────────────────────────────────────────────────────────────────────
  // 40. Meropenem
  // ─────────────────────────────────────────────────────────────────────────────
  static Map<String, String> _meropenem(String brand, String strength, String form, String company) => {
    'indications': '$brand ($strength $form) হাসপাতালে ভর্তি রোগীদের তীব্র ও জটিল সংক্রমণ যেমন নিউমোনিয়া, নোসোকোমিয়াল ইনফেকশন, ইন্ট্রা-অ্যাবডোমিনাল ইনফেকশন, ব্যাকটেরিয়াল মেনিনজাইটিস, সেপটিসেমিয়া এবং জটিল মূত্রনালীর ইনফেকশনে নির্দেশিত।',
    'pharmacology': 'মেরোপেনেম একটি আল্ট্রা-ব্রড স্পেকট্রাম কার্বাপেনেম অ্যান্টিবায়োটিক। এটি গ্রাম-পজিটিভ, গ্রাম-নেগেটিভ এবং সংবেদনশীল অবাত (Anaerobic) সব ধরনের ব্যাকটেরিয়ার পেনিসিলিন-বাইন্ডিং প্রোটিনকে (PBPs) নিষ্ক্রিয় করে ব্যাকটেরিয়ার কোষ প্রাচীর সংশ্লেষণ ধ্বংস করে দ্রুত ব্যাকটেরিসাইডাল ক্রিয়া প্রদর্শন করে।',
    'dosage_and_administration': 'প্রাপ্তবয়স্ক: ৫০০ মি.গ্রা. থেকে ১০০০ মি.গ্রা. প্রতি ৮ ঘণ্টা পর পর শিরায় ইনজেকশন বা ইনফিউশন (IV Infusion) হিসেবে। শিশুদের জন্য: ২০ থেকে ৪০ মি.গ্রা./কেজি প্রতি ৮ ঘণ্টা পর পর। শুধুমাত্র নিবন্ধিত চিকিৎসক ও প্রশিক্ষিত নার্সের তত্ত্বাবধানে হাসপাতালে প্রয়োগ করতে হবে।',
    'interaction': 'প্রোবেনেসিড মেরোপেনেমের রেনাল নিঃসরণ কমিয়ে রক্তে মাত্রা বাড়ায়। ভ্যালপ্রোয়িক অ্যাসিডের মাত্রা বিপজ্জনকভাবে কমিয়ে দিতে পারে, ফলে মৃগীরোগীদের খিঁচুনির তীব্র ঝুঁকি তৈরি হয়।',
    'contraindications': 'কার্বাপেনেম, পেনিসিলিন বা অন্যান্য বিটা-ল্যাকটাম অ্যান্টিবায়োটিকের প্রতি তীব্র অ্যানাফাইলেকটিক অতিসংবেদনশীলতায় সম্পূর্ণ নিষিদ্ধ।',
    'side_effects': 'ইনজেকশন প্রয়োগস্থলে ব্যথা ও প্রদাহ, ডায়রিয়া, বমি বমি ভাব, মাথাব্যথা, ত্বকে ফুসকুড়ি এবং রক্তে লিভার এনজাইম সাময়িক বৃদ্ধি।',
    'pregnancy_and_lactation': 'ইউএস এফডিএ প্রেগনেন্সি ক্যাটাগরি B। জীবনরক্ষাকারী প্রয়োজনে চিকিৎসকের বিবেচনায় ব্যবহার্য।',
    'precautions_and_warnings': 'কিডনি বৈকল্যের ক্ষেত্রে ক্রিয়েটিনিন ক্লিয়ারেন্সের ওপর ভিত্তি করে ডোজ সমন্বয় অপরিহার্য। খিঁচুনি বা স্নায়বিক জটিলতার ইতিহাস থাকলে সতর্কতা প্রয়োজন।',
    'overdose_effects': 'তীব্র মানসিক বিভ্রান্তি, খিঁচুনি ও কিডনি জটিলতা; হেমোডায়ালাইসিস দ্বারা ওষুধ অপসারিত হয়।',
    'therapeutic_class': 'Carbapenems (রিজার্ভ ব্রড-স্পেকট্রাম অ্যান্টিবায়োটিক)।',
    'storage_conditions': '২৫° সেলসিয়াসের নিচে শীতল স্থানে সংরক্ষণ করুন। তৈরি করা ইনজেকশন দ্রবণ ফ্রিজে রেখে ২৪ ঘণ্টার মধ্যে ব্যবহার করতে হয়।',
    'common_questions': '১. এই ইনজেকশন কি বাসায় নেওয়া যায়?\n- না, মেরোপেনেম একটি অত্যন্ত শক্তিশালী হাসপাতাল-গ্রেড রিজার্ভ অ্যান্টিবায়োটিক। এটি কেবল হাসপাতালের নিবিড় পর্যবেক্ষণে শিরায় দেওয়া হয়।',
  };

  // ─────────────────────────────────────────────────────────────────────────────
  // Universal Fallback Generator
  // ─────────────────────────────────────────────────────────────────────────────
  static Map<String, String> _synthesizeUniversal(
    String brand,
    String generic,
    String strength,
    String form,
    String company,
  ) {
    final cleanGeneric = generic.isEmpty ? 'এই ওষুধটি' : generic;
    final cleanBrand = brand.isEmpty ? 'ঔষধ' : brand;
    final isDrop = form.toLowerCase().contains('drop');
    final isOintment = form.toLowerCase().contains('cream') || form.toLowerCase().contains('ointment') || form.toLowerCase().contains('gel');
    final isSyrup = form.toLowerCase().contains('syrup') || form.toLowerCase().contains('suspension');
    final isInjection = form.toLowerCase().contains('injection') || form.toLowerCase().contains('infusion');

    String usage;
    if (isDrop) {
      usage = 'প্রয়োগবিধি: আক্রান্ত চোখ বা কানে নির্দিষ্ট ফোঁটা অনুযায়ী দিনে ২-৩ বার ড্রপ দিতে হবে। ড্রপারের মুখে স্পর্শ করা নিষেধ এবং ড্রপ দেওয়ার পর চোখ কিছুক্ষণ বন্ধ রাখুন।';
    } else if (isOintment) {
      usage = 'প্রয়োগবিধি: আক্রান্ত স্থান পরিষ্কার ও শুষ্ক করে হালকা স্তরে মেখে দিতে হবে। ব্যবহারের পূর্বে ও পরে হাত সাবান দিয়ে ধুয়ে নিন। চোখে বা মুখে লাগানো পরিহার করুন।';
    } else if (isSyrup) {
      usage = 'ডোজ ও ব্যবহারবিধি: বোতলটি ব্যবহারের পূর্বে ভালোভাবে ঝাঁকিয়ে নিন। পরিমাপক চামচ বা কাপ দিয়ে সঠিক মাত্রায় সেবন করুন। শিশুদের ক্ষেত্রে ওজন ও বয়স অনুযায়ী ডাক্তারের পরামর্শে ব্যবহার্য।';
    } else if (isInjection) {
      usage = 'প্রয়োগবিধি: এটি শিরায় (IV) বা মাংসপেশিতে (IM) প্রয়োগযোগ্য। শুধুমাত্র রেজিস্টার্ড চিকিৎসক বা অভিজ্ঞ নার্সের তত্ত্বাবধানে উপযুক্ত পরিবেশে প্রয়োগ করতে হবে।';
    } else {
      usage = 'ডোজ ও ব্যবহারবিধি: প্রাপ্তবয়স্ক ও নির্দিষ্ট রোগীদের ক্ষেত্রে চিকিৎসকের পরামর্শ অনুযায়ী নিয়মিত সময়ে সেবনযোগ্য। ট্যাবলেট বা ক্যাপসুল পর্যাপ্ত পানিসহ সম্পূর্ণ গিলে খেতে হবে; না চিবিয়ে বা গুঁড়ো না করে খাওয়া শ্রেয়। গ্যাস্ট্রিক সুরক্ষার জন্য খাবার গ্রহণের পর সেবন করা উত্তম।';
    }

    return {
      'indications': '$cleanBrand ($cleanGeneric $strength $form) সংশ্লিষ্ট রোগের চিকিৎসার জন্য চিকিৎসকের ব্যবস্থাপত্র অনুযায়ী নির্দেশিত। এটি ক্লিনিক্যাল প্রোটোকল অনুযায়ী রোগীর শারীরিক পরীক্ষা ও উপসর্গের ওপর ভিত্তি করে প্রয়োগ করা হয়।',
      'pharmacology': '$cleanGeneric এর সক্রিয় উপাদান কোষীয় বা আণবিক পর্যায়ে নির্দিষ্ট রিসেপ্টর বা এনজাইমের ওপর কাজ করে রোগের প্রতিকার সাধন করে এবং শারীরবৃত্তীয় ভারসাম্য ফিরিয়ে আনতে সাহায্য করে।',
      'dosage_and_administration': usage,
      'interaction': 'যেকোনো নতুন ওষুধ, প্রেসক্রিপশন বহির্ভূত খাদ্য সম্পূরক বা ভেষজ ওষুধ গ্রহণের পূর্বে আপনার চিকিৎসকের সাথে আলোচনা করুন। একই সাথে একাধিক ওষুধ ব্যবহারে পারস্পরিক ক্রিয়া হতে পারে।',
      'contraindications': '$cleanGeneric বা সংশ্লিষ্ট রাসায়নিক ফর্মুলেশনের প্রতি পরিচিত অতিসংবেদনশীলতা (Allergy) থাকলে ব্যবহার পরিহার করুন।',
      'side_effects': 'সাধারণ পার্শ্বপ্রতিক্রিয়ার মধ্যে মৃদু পেটে অস্বস্তি, মাথা ঘোরা, বমি বমি ভাব বা ত্বকে ফুসকুড়ি হতে পারে। যেকোনো অনাকাঙ্ক্ষিত উপসর্গ অব্যাহত থাকলে চিকিৎসকের পরামর্শ নিন।',
      'pregnancy_and_lactation': 'গর্ভাবস্থায় ও স্তন্যদানকালীন সময়ে ব্যবহারের পূর্বে অবশ্যই রেজিস্টার্ড চিকিৎসকের পরামর্শ গ্রহণ করতে হবে। সম্ভাব্য সুফল ঝুঁকির চেয়ে বেশি হলে তবেই ব্যবহার্য।',
      'precautions_and_warnings': 'লিভার বা কিডনির জটিলতা থাকলে চিকিৎসকের পরামর্শে ডোজ সমন্বয় প্রয়োজন। চিকিৎসকের নির্দেশিত মেয়াদের অতিরিক্ত সময় ওষুধ ব্যবহার করবেন না। শিশুদের নাগালের বাইরে রাখুন।',
      'overdose_effects': 'অতিরিক্ত মাত্রায় ওষুধ গ্রহণ করলে অবিলম্বে নিকটস্থ স্বাস্থ্যকেন্দ্রে যোগাযোগ করুন এবং ওষুধের প্যাকেটটি সাথে রাখুন।',
      'therapeutic_class': 'Prescription Pharmaceutical / $cleanGeneric।',
      'storage_conditions': 'আলো ও সরাসরি তাপ থেকে দূরে, ৩০° সেলসিয়াসের নিচে শীতল ও শুষ্ক স্থানে সংরক্ষণ করুন। স্যাঁতসেঁতে স্থানে রাখবেন না।',
      'common_questions': '১. ডোজ ভুলে গেলে কি করবেন?\n- মনে পড়ার সাথে সাথে ডোজটি গ্রহণ করুন। তবে পরবর্তী ডোজের সময় কাছাকাছি হলে ভুলে যাওয়া ডোজটি বাদ দিন; ভুলেও একসাথে ডাবল ডোজ খাবেন না।\n\n২. ওষুধটি কতদিন খেতে হবে?\n- চিকিৎসকের নির্দেশিত পূর্ণ মেয়াদ পর্যন্ত নিয়মিত ওষুধ সেবন করুন।',
